mapper.select:
SELECT f.task_id, f.cruise_data_id, f.device_mete_id, f.cruise_time, f.cruise_type, f.instance_name, f.person_check, f.modify_num, f.result_num, f.result_desc, f.identify_result, f.cruise_result, f.picpath as picPath, a.mete_type, a.meter_type FROM u_patrol_data_result f LEFT JOIN t_std_devicemete a on a.device_mete_id = f.device_mete_id WHERE a.device_mete_id in (
#{deviceMeteId, jdbcType=BIGINT}
) and f.cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP} and f.cruise_type = #{cruiseType, jdbcType=INTEGER} and a.mete_type = #{meteType, jdbcType=VARCHAR} and a.meter_type = #{meterType, jdbcType=INTEGER} ORDER BY f.cruise_time DESC

SELECT a.device_mete_id, a.mete_type, a.meter_type, e.cruise_time, e.cruise_type, e.instance_name, e.result_num, e.result_desc, e.person_check, e.identify_result, e.cruise_result, e.picpath AS picPath, e.origpic, e.device_name AS device_name, e.evaluation_state AS evaluation_state, e.task_id, e.instance_id, e.device_id, tsd.device_type AS device_type, tsd.up_region_name AS up_region_name, tsd.up_region_id AS region_id FROM u_patrol_data_result e LEFT JOIN t_std_devicemete a ON a.device_mete_id = e.device_mete_id Left Join t_std_device tsd on e.device_id = tsd.device_id WHERE 1 = 1 and e.device_id IN
#{deviceIds,jdbcType=BIGINT}
and e.cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
and a.mete_type = #{meteType, jdbcType=VARCHAR} and a.meter_type = #{meterType, jdbcType=INTEGER}
and e.instance_name like CONCAT('%',CONCAT(#{instanceName},'%'))
ORDER BY e.cruise_time DESC

SELECT a.device_mete_id as deviceMeteId, a.mete_type as meteType, a.meter_type as meterType, e.cruise_time as cruiseTime, e.cruise_type as cruiseType, e.instance_name as instanceName, e.result_num as resultNum, e.result_desc as resultDesc, IFNULL(e.person_check,'') as personCheck, e.identify_result as identifyResult, e.cruise_result as cruiseResult, e.picpath AS picPath, case e.origpic when 'null' then '' else e.origpic end as origpic, e.device_name AS deviceName, e.evaluation_state AS evaluationState, e.task_id as taskId, e.instance_id as instanceId, e.device_id as deviceId, tsd.device_type AS deviceType, tsd.up_region_name AS upRegionName, tsd.up_region_id AS regionId, (select warn_level from t_warn_info where task_id = e.task_id and instance_id = e.instance_id limit 1) AS alarmLevel FROM u_patrol_data_result e LEFT JOIN t_std_devicemete a ON a.device_mete_id = e.device_mete_id Left Join t_std_device tsd on e.device_id = tsd.device_id WHERE 1 = 1 and e.device_id IN
#{deviceIds,jdbcType=BIGINT}
and e.cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
and a.mete_type = #{meteType, jdbcType=VARCHAR} and a.meter_type = #{meterType, jdbcType=INTEGER}
and e.instance_name like CONCAT('%',CONCAT(#{instanceName},'%'))
ORDER BY e.cruise_time DESC

SELECT f.cruise_time, if(f.modify_num is null,f.result_num,f.modify_num) resultNum, if(f.modify_num is null,f.result_desc,f.person_check) resultDesc, f.instance_name, f.cruise_type, f.cruise_device_id, f.cruise_device_name, a.mete_name, a.mete_type, a.meter_type, a.device_mete_id, f.identify_result, f.cruise_result, f.picpath AS picPath, f.origpic, f.device_name FROM u_patrol_data_result f LEFT JOIN t_std_devicemete a on a.device_mete_id = f.device_mete_id WHERE a.device_mete_id in (
#{deviceMeteId, jdbcType=BIGINT}
) and f.cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP} and f.cruise_type=#{cruiseType,jdbcType=INTEGER} and a.meter_type=#{meterType,jdbcType=INTEGER} and a.mete_type=#{meteType,jdbcType=VARCHAR} ORDER BY f.cruise_time ASC

mapper.update:
UPDATE t_std_devicemete_update a INNER JOIN ( SELECT * FROM ( SELECT c.device_mete_id, c.cruise_time, c.picpath, c.cruise_result, c.identify_result FROM u_patrol_data_result c WHERE c.task_id = #{taskId,jdbcType=VARCHAR} ORDER BY c.cruise_time DESC LIMIT 999999 ) big_table GROUP BY big_table.device_mete_id ) b ON a.device_mete_id = b.device_mete_id
a.update_time = b.cruise_time, a.cruise_result = b.cruise_result, a.identify_result = b.identify_result, a.pic_path = b.picpath
WHERE a.update_time < b.cruise_time;
